// taking a write lock (and thus blocking on live method calls). However, we aim not to
// generate methods with any hidden blocking semantics, and a `destroy` method that might
// block if called incorrectly seems to meet that bar.
//
// So, we achieve our goals by giving each instance an associated `AtomicLong` counter to track
// the number of in-flight method calls, and an `AtomicBoolean` flag to indicate whether `destroy`
// has been called. These are updated according to the following rules:
//
//    * The initial value of the counter is 1, indicating a live object with no in-flight calls.
//      The initial value for the flag is false.
//
//    * At the start of each method call, we atomically check the counter.
//      If it is 0 then the underlying Rust struct has already been destroyed and the call is aborted.
//      If it is nonzero them we atomically increment it by 1 and proceed with the method call.
//
//    * At the end of each method call, we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
//    * When `destroy` is called, we atomically flip the flag from false to true.
//      If the flag was already true we silently fail.
//      Otherwise we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
// Astute readers may observe that this all sounds very similar to the way that Rust's `Arc<T>` works,
// and indeed it is, with the addition of a flag to guard against multiple calls to `destroy`.
//
// The overall effect is that the underlying Rust struct is destroyed only when `destroy` has been
// called *and* all in-flight method calls have completed, avoiding violating any of the expectations
// of the underlying Rust code.
//
// This makes a cleaner a better alternative to _not_ calling `destroy()` as
// and when the object is finished with, but the abstraction is not perfect: if the Rust object's `drop`
// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


public interface HamsEngineInterface {
    
    /**
     * Whether Undo / Rewrite still apply to the field under the keyboard.
     */
    fun `canUndo`(): kotlin.Boolean
    
    /**
     * Throw the current recording away.
     */
    fun `cancel`()
    
    fun `defaultAiModel`(`provider`: kotlin.String): kotlin.String
    
    fun `deleteModel`(`id`: kotlin.String)
    
    fun `dictionaryDelete`(`id`: kotlin.Long)
    
    fun `dictionaryJson`(): kotlin.String
    
    /**
     * Add a word ("Tauri"), or a replacement when `replacement` is set
     * (`term` is what Whisper hears).
     */
    fun `dictionaryUpsert`(`term`: kotlin.String, `replacement`: kotlin.String?)
    
    /**
     * Blocking (network). Download a model; resumes an interrupted download.
     */
    fun `downloadModel`(`id`: kotlin.String, `listener`: DownloadListener)
    
    /**
     * Delete all history except pinned items.
     */
    fun `historyClear`()
    
    fun `historyDelete`(`id`: kotlin.Long)
    
    /**
     * JSON array of `HistoryItem` matching `query` (full-text), pinned first.
     */
    fun `historyJson`(`query`: kotlin.String, `limit`: kotlin.Long): kotlin.String
    
    fun `historyPin`(`id`: kotlin.Long, `pinned`: kotlin.Boolean)
    
    /**
     * JSON array of `HistoryItem`, newest first (pinned not moved up).
     */
    fun `historyRecentJson`(`limit`: kotlin.Long): kotlin.String
    
    /**
     * Blocking (may call the AI). Rewrite a history item in `style`, save it in
     * place, and return `{"text": …, "polished": bool}`.
     */
    fun `historyRestyle`(`id`: kotlin.Long, `style`: kotlin.String): kotlin.String
    
    /**
     * Save an edit; learns suggested corrections from it when enabled. Returns how many.
     */
    fun `historyUpdate`(`id`: kotlin.Long, `text`: kotlin.String): kotlin.UInt
    
    fun `isRecording`(): kotlin.Boolean
    
    /**
     * Blocking (disk). The newest dictation, for the Heard / Written strip.
     */
    fun `lastDictation`(): Dictation?
    
    /**
     * Whether the selected model is downloaded (the keyboard can't work without it).
     */
    fun `modelReady`(): kotlin.Boolean
    
    /**
     * JSON array of phone models: `{id, file, label, size_mb, multilingual, note, mobile, installed}`.
     */
    fun `modelsJson`(): kotlin.String
    
    /**
     * The mic pad went down. Hold to talk; tap twice quickly for hands-free.
     */
    fun `press`(`pad`: Pad)
    
    /**
     * Mono audio in -1..1 from the microphone, while recording.
     */
    fun `pushAudio`(`frames`: List<kotlin.Float>, `sampleRate`: kotlin.UInt)
    
    /**
     * 16-bit PCM from the microphone, while recording.
     */
    fun `pushAudioI16`(`frames`: List<kotlin.Short>, `sampleRate`: kotlin.UInt)
    
    /**
     * 16-bit little-endian PCM bytes straight from `AudioRecord.read(ByteArray)`:
     * the cheapest way across the FFI (no boxed samples).
     */
    fun `pushAudioPcm16`(`bytes`: kotlin.ByteArray, `sampleRate`: kotlin.UInt)
    
    /**
     * JSON array of app names seen in history (for per-app style rules).
     */
    fun `recentAppsJson`(): kotlin.String
    
    /**
     * The mic pad came up.
     */
    fun `release`(`pad`: Pad)
    
    /**
     * Free the speech model (the phone is low on memory). It loads again on
     * the next dictation.
     */
    fun `releaseModel`()
    
    /**
     * Blocking (may call the AI). Rewrite the last dictation in `style`
     * ("messaging", "email", …), replace it in the field and in history, and
     * return the new text.
     */
    fun `restyleLast`(`style`: kotlin.String): kotlin.String
    
    /**
     * Blocking (disk). Validate and save the settings object.
     */
    fun `saveSettingsJson`(`settings`: kotlin.String)
    
    /**
     * Save (or with an empty key, remove) the API key for `provider` ("gemini", "anthropic", …).
     */
    fun `setApiKey`(`provider`: kotlin.String, `key`: kotlin.String)
    
    /**
     * `{"settings": {...}, "has_api_key": bool}`. The settings object is the
     * desktop app's `Settings` (see `src/lib/bindings.ts`); change fields in
     * place and send the whole object back to keep fields this app doesn't know.
     */
    fun `settingsJson`(): kotlin.String
    
    fun `snippetDelete`(`id`: kotlin.Long)
    
    fun `snippetUpsert`(`trigger`: kotlin.String, `expansion`: kotlin.String)
    
    fun `snippetsJson`(): kotlin.String
    
    /**
     * JSON `Stats`.
     */
    fun `statsJson`(): kotlin.String
    
    /**
     * Finish the current recording and insert it.
     */
    fun `stop`()
    
    /**
     * Blocking (may call the AI). Run spoken text through a style without
     * saving anything. Returns `{"text": …, "polished": bool}`.
     */
    fun `styleTry`(`style`: kotlin.String, `text`: kotlin.String): kotlin.String
    
    /**
     * JSON array of `{id, label, prompt, polish}` for the built-in styles.
     */
    fun `stylesJson`(): kotlin.String
    
    fun `suggestionResolve`(`id`: kotlin.Long, `approve`: kotlin.Boolean)
    
    fun `suggestionsJson`(): kotlin.String
    
    /**
     * Blocking (network). Send a sample sentence through the configured provider.
     */
    fun `testAi`(): kotlin.String
    
    /**
     * Start hands-free, or finish the current recording.
     */
    fun `toggle`()
    
    /**
     * Remove the last inserted dictation, if it's still right before the cursor.
     */
    fun `undoLast`(): kotlin.Boolean
    
    /**
     * Load the speech model in the background so the first dictation is fast.
     */
    fun `warmUp`()
    
    companion object
}

open class HamsEngine: Disposable, AutoCloseable, HamsEngineInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }
    /**
     * Open (or create) the database in `data_dir` and start the engine.
     * Create one per process and keep it for the life of the app.
     */
    constructor(`dataDir`: kotlin.String, `host`: Host, `vault`: SecretVault) :
        this(UniffiWithHandle, 
    uniffiRustCallWithError(HamsException) { _status ->
    UniffiLib.uniffi_hams_mobile_fn_constructor_hamsengine_new(
    
        
        FfiConverterString.lower(`dataDir`),
        FfiConverterTypeHost.lower(`host`),
        FfiConverterTypeSecretVault.lower(`vault`),_status)
}
    )

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_hams_mobile_fn_free_hamsengine(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_hams_mobile_fn_clone_hamsengine(handle, status)
        }
    }

    
    /**
     * Whether Undo / Rewrite still apply to the field under the keyboard.
     */override fun `canUndo`(): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_hams_mobile_fn_method_hamsengine_can_undo(
        it,
        _status)
}
    }
    )
    }
    

    
