sealed class HamsException: kotlin.Exception() {
    
    /**
     * Every failure carries a sentence that can be shown to the user as is.
     * (Named `reason`: `message` would clash with Kotlin's Throwable.message.)
     */
    class Failed(
        
        val `reason`: kotlin.String
        ) : HamsException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<HamsException> {
        override fun lift(error_buf: RustBuffer.ByValue): HamsException = FfiConverterTypeHamsError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeHamsError : FfiConverterRustBuffer<HamsException> {
    override fun read(buf: ByteBuffer): HamsException {
        

        return when(buf.getInt()) {
            1 -> HamsException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: HamsException): ULong {
        return when(value) {
            is HamsException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: HamsException, buf: ByteBuffer) {
        when(value) {
            is HamsException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



